package com.rohit.inventory.service;
import com.rohit.inventory.dto.response.RoleResponse; import com.rohit.inventory.exception.ResourceNotFoundException; import com.rohit.inventory.mapper.RoleMapper; import com.rohit.inventory.repository.RoleRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class RoleService { private final RoleRepository roles; private final RoleMapper mapper; public RoleService(RoleRepository roles,RoleMapper mapper){this.roles=roles;this.mapper=mapper;} public List<RoleResponse> list(){return roles.findAll().stream().map(mapper::toResponse).sorted(Comparator.comparing(RoleResponse::code)).toList();} public RoleResponse get(UUID id){return mapper.toResponse(roles.findById(id).orElseThrow(()->new ResourceNotFoundException("Role not found")));} }
